/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LookupAction, FoundRelease, LookupStepResult, LookupStep, LookupStepClients
 *   Functions: performLookupStep, lookupAliasTargets, endLookupRun, proceedLookupRun
 *   Constants: idleLookupStep
 * Internal
 *   Types: Exhausted
 *   Functions: actionSource, searchStep, recordAliases, failPendingAliases, exhaustedIssue, storedExhausted
 * @end-catalog */

/**
 * One step of a metadata lookup run, without a database: the request a step performs (outside any transaction) and the pure
 * decision that stores its answer and chooses the next request. A run sends its planned queries in order (the fallbacks only when
 * the searches before them found no candidate) until 25 candidates are known, admitting first the releases whose reported track
 * count can equal the number of files (the count is only used here, never sent), then fetches each pending candidate's details
 * (those plausible releases first). When MusicBrainz then has no matching candidate (or its searches stayed unavailable), and, in
 * an existing-Album review, no release of the searched title whose credit agrees and whose tracks fit
 * (catalogReviewItunesSkippable), the iTunes stage runs (lookupItunesStage.ts): its UPC lookups and searches, the bridge searches
 * of the names found (their releases merged and fetched like any search's), then a collection lookup for each result the bridge did
 * not find, which becomes an iTunes-only candidate. Last, it looks up the aliases of at most 16 credited artists and labels (in
 * ranked order, each once, never a placeholder; a source failure ends the alias phase, recording every remaining target as failed
 * and never retrying, so value application never waits for an outage), then ranks with them and the iTunes localized names. It
 * records whether its searches were complete, so a lone matching group of a partial comparison is never preselected. An
 * existing-Album review's run compares in subset mode: releases are admitted and fetched fewest extra tracks first, its searches
 * record a second completeness flag for the exact-count preselection, its iTunes stage keeps collections with at least as many
 * tracks as members with that flag of its own, and its alias targets add each fetched release's track artists. A review whose plan
 * ends in Track-title searches keeps 10 of the 25 release lookups for them while they are undecided; once the title searches'
 * releases are compared, it sends them (in wait mode, each admitting at most 5 releases) only when that comparison preselects
 * nothing, before the iTunes stage, and records the decision. Per attempt a run sends at most
 * `METADATA_LOOKUP_LIMITS.plannedQueries` searches, `METADATA_LOOKUP_JOB_LIMITS.candidates` release lookups and `aliasLookups`
 * alias lookups to MusicBrainz, and alongside them at most `bridgeSearches` bridge searches and, to iTunes, `itunesUpcLookups` UPC
 * lookups, `itunesSearches` searches and `itunesCollectionLookups` collection lookups: at most 60 requests, each through its
 * source's gate. metadataLookupService.ts stores each step.
 */
import type { AdminImportDocument } from '../import/adminImportService';
import {
    METADATA_LOOKUP_JOB_LIMITS as JOB, MetadataLookupInputError, MetadataLookupSourceError,
    type ItunesSearchResult, type LookupEntityAliases, type LookupGateMode, type MusicBrainzRelease, type MusicBrainzReleaseSummary
} from './lookupContract';
import type { ItunesSearchClient } from './iTunesSearchClient';
import { isPlaceholderCredit, normalizeMusicBrainzId } from './lookupIdentifiers';
import { keepableMusicBrainzId } from '../../utils/musicBrainzId';
import {
    itunesCandidate, itunesUnavailable, lookupLocalizedGroups, nextItunesCollectionAction, nextItunesSearchAction, recordBridgeAnswer, recordItunesAnswer,
    recordItunesCollection, skipItunesRequest, startItunesStage, storedItunesStage, type LookupItunesAction, type LookupItunesStage
} from './lookupItunesStage';
import { isFallbackLookupQuery, isTrackTitleLookupQuery, trackTitleLookupTiming, type PlannedLookupQuery } from './lookupQueryPlanner';
import { lookupTrackCountPlausible, lookupTrackCredit } from './lookupRanking';
import { catalogReviewItunesSkippable, lookupComparisonFor } from './lookupReviewEvidence';
import { lookupAudioTrackCount, lookupSurplusRank, releaseAudioTracks } from './lookupSubset';
import { trackTitleWeight, UNCREDITED_TRACK_TITLE_MIN_WEIGHT } from './lookupTrackTitles';
import type { MusicBrainzClient } from './musicBrainzClient';
import {
    admitItunesCandidate, lookupEvidenceFor, lookupFetchedAliases, lookupHitsAdmitted, lookupReportedTrackCount, lookupRetryAt, lookupSubsetHitsAdmitted, mergeLookupCandidates,
    rankLookupWithinBudget, recordLookupDetails, type MetadataLookupIssue, type MetadataLookupRecord, type MetadataLookupState, type StoredLookupCandidate, type StoredLookupRanking
} from './metadataLookupRecord';

export type LookupAction = { kind: 'search'; index: number; query: PlannedLookupQuery } | { kind: 'details'; releaseId: string }
    | { kind: 'aliases'; entity: 'artist' | 'label'; id: string } | LookupItunesAction;
/** A release a search offered, with the track count it reported (a recording hit's release has no summary). */
export type FoundRelease = { releaseId: string; summary?: MusicBrainzReleaseSummary; release?: MusicBrainzRelease; trackCount?: number | null };
/**
 * What one request answered, mapped so that the step that stores it never needs the source's errors. A search (planned or bridge)
 * is `complete` when it returned every hit it reported; a 503/429 that outlasted the request's own retries is `rateLimited`. A
 * failure names its source, whose automatic retries it counts against.
 */
export type LookupStepResult =
    | { kind: 'found'; action: LookupAction & { kind: 'search' | 'bridge' }; found: FoundRelease[]; complete: boolean }
    | { kind: 'details'; action: LookupAction & { kind: 'details' }; release: MusicBrainzRelease | null }
    /** `names` null: MusicBrainz answered 404 or for another ID. */
    | { kind: 'aliases'; action: LookupAction & { kind: 'aliases' }; names: string[] | null }
    /** `result` null: the storefront has no release with that barcode. */
    | { kind: 'itunes'; action: LookupAction & { kind: 'itunes' }; result: ItunesSearchResult | null }
    /** `result` null: the storefront has no such collection. */
    | { kind: 'itunesCollection'; action: LookupAction & { kind: 'itunesCollection' }; result: ItunesSearchResult | null }
    | { kind: 'refused'; action: LookupAction }
    | { kind: 'failed'; source: 'musicbrainz' | 'itunes'; failure: 'busy' | 'rateLimited' | 'unavailable'; retryAfterMs: number | null }
    | { kind: 'notConfigured' }
    | { kind: 'shutdown' };
export type LookupStep = { action: LookupAction | null; mode: LookupGateMode };
export const idleLookupStep: LookupStep = { action: null, mode: 'wait' };
/** The clients a step may call: MusicBrainz for searches, release and alias lookups, iTunes for the fallback stage. */
export type LookupStepClients = { musicBrainz: MusicBrainzClient; itunes: ItunesSearchClient };

const actionSource = (action: LookupAction): 'musicbrainz' | 'itunes' => action.kind === 'itunes' || action.kind === 'itunesCollection' ? 'itunes' : 'musicbrainz';
/** A planned or bridge search; a query kind a later release stored is skipped rather than sent. */
async function searchStep(client: MusicBrainzClient, action: LookupAction & { kind: 'search' | 'bridge' }, options: { mode: LookupGateMode; signal: AbortSignal }): Promise<LookupStepResult> {
    const found = (items: FoundRelease[], complete: boolean): LookupStepResult => ({ kind: 'found', action, found: items, complete });
    const { query } = action;
    switch (query.kind) {
        // Keyed by the release MusicBrainz returned: a merged release answers an old ID with its current one.
        case 'musicBrainzRelease': { const release = await client.lookupRelease(query.releaseId, options); return found(release ? [{ releaseId: release.releaseId, release }] : [], true); }
        case 'musicBrainzReleaseSearch': {
            const result = await client.searchReleases(query.query, options);
            return found(result.releases.map(summary => ({ releaseId: summary.releaseId, summary })), result.count <= result.releases.length);
        }
        case 'musicBrainzRecordingSearch': {
            const result = await client.searchRecordings(query.query, options);
            return found(result.recordings.flatMap(hit => hit.releases.map(release => ({ releaseId: release.releaseId, trackCount: release.trackCount }))),
                result.count <= result.recordings.length);
        }
        case 'musicBrainzIsrc': return found(((await client.lookupIsrc(query.isrc, options))?.recordings ?? []).flatMap(recording => recording.releaseIds.map(releaseId => ({ releaseId }))), true);
        default: return { kind: 'refused', action };
    }
}

/**
 * Performs one request outside any transaction, bounded by the step deadline; never throws. An alias lookup and a Track-title search
 * always wait for their gate, so a busy gate in a submitted run never refuses an optional search.
 */
export async function performLookupStep(clients: LookupStepClients, action: LookupAction, mode: LookupGateMode, signal?: AbortSignal): Promise<LookupStepResult> {
    const deadline = AbortSignal.timeout(JOB.stepDeadlineMs);
    const waits = action.kind === 'aliases' || (action.kind === 'search' && isTrackTitleLookupQuery(action.query));
    const options = { mode: waits ? 'wait' as const : mode, signal: signal ? AbortSignal.any([signal, deadline]) : deadline };
    try {
        if (action.kind === 'details') return { kind: 'details', action, release: await clients.musicBrainz.lookupRelease(action.releaseId, options) };
        if (action.kind === 'aliases') return { kind: 'aliases', action, names: (await clients.musicBrainz.lookupAliases(action.entity, action.id, options))?.names ?? null };
        if (action.kind === 'itunes') {
            const { request } = action;
            const result = request.kind === 'itunesUpc' ? await clients.itunes.lookupUpc(request.barcode, request.storefront, options)
                : request.kind === 'itunesSearch' && request.entity === 'song' ? await clients.itunes.searchSongs(request.term, request.storefront, options)
                    : request.kind === 'itunesSearch' && request.entity === 'album' ? await clients.itunes.searchCollections(request.term, request.storefront, options) : undefined;
            return result === undefined ? { kind: 'refused', action } : { kind: 'itunes', action, result };
        }
        if (action.kind === 'itunesCollection') return { kind: 'itunesCollection', action, result: await clients.itunes.lookupCollection(action.collectionId, action.storefront, options) };
        if (action.kind === 'search' || action.kind === 'bridge') return await searchStep(clients.musicBrainz, action, options);
        return { kind: 'refused', action };
    } catch (error) {
        if (error instanceof MetadataLookupInputError) return { kind: 'refused', action };
        if (signal?.aborted) return { kind: 'shutdown' };
        if (error instanceof MetadataLookupSourceError) {
            if (error.failure === 'notConfigured') return { kind: 'notConfigured' };
            // `cancelled` here is the step deadline: the source did not answer in time.
            const failure = error.failure === 'busy' ? 'busy' : error.failure === 'rateLimited' ? 'rateLimited' : 'unavailable';
            return { kind: 'failed', source: error.source === 'itunes' || error.source === 'musicbrainz' ? error.source : actionSource(action), failure, retryAfterMs: error.retryAfterMs };
        }
        return { kind: 'failed', source: actionSource(action), failure: 'unavailable', retryAfterMs: null };
    }
}

/**
 * The credited artists and the first label whose aliases a run looks up: candidates in ranked order (the preselected one first,
 * then the ranking's order), each fetched release's credited artist IDs in credit order and then its first label's ID, and with
 * `trackArtists` (a review run, whose member credits compare with track credits) then the artist IDs its audio tracks credit, in
 * track order, before the next release; each once, never a placeholder, at most `JOB.aliasLookups`. An iTunes-only candidate
 * credits no MusicBrainz ID, so it adds none.
 */
export function lookupAliasTargets(candidates: readonly StoredLookupCandidate[], ranking: Pick<StoredLookupRanking, 'candidates' | 'preselection'> | null,
    options: { trackArtists?: boolean } = {}): LookupEntityAliases[] {
    const order = [ranking?.preselection?.candidateKey, ...(ranking?.candidates ?? []).map(candidate => candidate.key), ...candidates.map(candidate => candidate.key)];
    const targets: LookupEntityAliases[] = [], seen = new Set<string>();
    const add = (kind: 'artist' | 'label', raw: unknown, name: unknown) => {
        const id = keepableMusicBrainzId(raw);
        if (!id || isPlaceholderCredit(name, id) || seen.has(`${kind}:${id}`) || targets.length >= JOB.aliasLookups) return;
        seen.add(`${kind}:${id}`); targets.push({ kind, id, state: 'pending', names: [] });
    };
    for (const key of [...new Set(order)]) {
        const release = candidates.find(candidate => candidate.key === key && candidate.details === 'fetched')?.release;
        if (!release || normalizeMusicBrainzId(release.releaseId) === null) continue;
        for (const credit of release.artistCredit) add('artist', credit.artistId, credit.name);
        const label = release.labels.find(item => item.name !== null || item.labelId !== null);
        if (label) add('label', label.labelId, label.name);
        if (options.trackArtists) for (const { track } of releaseAudioTracks(release).tracks) for (const credit of lookupTrackCredit(release, track) ?? []) add('artist', credit.artistId, credit.name);
    }
    return targets;
}

/** Ends a run: the lease and retry are cleared and nothing else from the step that ended it is stored. */
export const endLookupRun = (record: MetadataLookupRecord, state: MetadataLookupState, issue: MetadataLookupIssue | null, now: Date,
    extra: Partial<MetadataLookupRecord> = {}): MetadataLookupRecord =>
    ({ ...record, ...extra, state, issue, retryAt: null, leaseOwner: null, leaseUntil: null, updatedAt: now, completedAt: now });

/** Records one alias lookup's outcome on the first pending target it names. */
const recordAliases = (aliases: readonly LookupEntityAliases[], target: { entity: 'artist' | 'label'; id: string }, outcome: Pick<LookupEntityAliases, 'state' | 'names'>) => {
    const index = aliases.findIndex(entry => entry.state === 'pending' && entry.kind === target.entity && entry.id === target.id);
    return index < 0 ? [...aliases] : aliases.map((entry, at) => at === index ? { ...entry, ...outcome, names: outcome.names.slice(0, JOB.aliasNames) } : entry);
};
/** A source failure in the alias phase ends it: every pending target is recorded as failed, so an outage is not asked again. */
const failPendingAliases = (aliases: readonly LookupEntityAliases[]) => aliases.map(entry => entry.state === 'pending' ? { ...entry, state: 'failed' as const, names: [] } : entry);
type Exhausted = NonNullable<MetadataLookupRecord['exhausted']>;
const exhaustedIssue = (value: unknown) => value === 'sourceBusy' || value === 'sourceUnavailable' ? value : undefined;
/** The stored exhausted sources this release reads (a record from an earlier release has none). */
const storedExhausted = (raw: unknown): Exhausted => {
    const value = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {};
    const musicbrainz = exhaustedIssue(value.musicbrainz), itunes = exhaustedIssue(value.itunes);
    return { ...(musicbrainz ? { musicbrainz } : {}), ...(itunes ? { itunes } : {}) };
};

/**
 * Stores one request's result and decides the next request (pure): the planned queries in order until 25 candidates are known (the
 * fallbacks are skipped when a candidate is known as they start), then each pending candidate's details (plausible track counts
 * first), then, when MusicBrainz has no matching candidate and the iTunes stage is needed (itunesNotNeeded: an existing-Album
 * review also skips it for a release of the searched title whose credit agrees and whose tracks fit), the iTunes stage (its
 * requests, its bridge searches before the bridged releases' details, then its collection lookups), then the alias lookups
 * (lookupAliasTargets; skipped once MusicBrainz is exhausted), then ranking. A source failure schedules an automatic retry of that
 * source, a throttled first failure within seconds. Once MusicBrainz's retries run out it is exhausted for the run: no further
 * search, release or alias lookup is sent, pending details are failed (incomplete), unsent bridge searches leave their results
 * unavailable, and, without a stage yet, the iTunes stage starts if it is needed (else a search phase ends unavailable, never "no
 * release", as does a stage started that way that finds no iTunes-only candidate). Once iTunes's retries run out, its remaining
 * requests are skipped and the run completes with what it has. A source failure of an alias lookup (busy, throttled or unavailable)
 * records it and every remaining alias target as failed and ranks in the same step, never retried or counted as an attempt; a
 * refused one fails only its target. A record without `aliases`, `itunesStage` or `exhausted`, from an earlier release, completes
 * without them. Track-title searches (an existing-Album review's plan tail): while they are undecided, title searches admit at most
 * 15 releases and are handed out only below that bound (a bound stop is partial and moves to the decision). Once no detail is
 * pending, they are skipped when MusicBrainz is exhausted, the ranking preselects, or, with title searches that named an Artist, a
 * complete comparison has a matching group; otherwise they are sent, credited as planned unless those credited searches returned no
 * release (then alone, and only titles weighing at least eight), each admitting at most 5 releases. One the source does not answer
 * ends them without a retry or an attempt, leaving the comparison partial. A matching group found only by Track titles never stops
 * the iTunes stage. A stored record past them, or with an iTunes stage, while undecided records them as skipped.
 */
export function proceedLookupRun(record: MetadataLookupRecord, doc: AdminImportDocument, result: LookupStepResult | null, now: Date): { next: MetadataLookupRecord; step: LookupStep } {
    let next: MetadataLookupRecord = { ...record, updatedAt: now };
    // A review's run binds its members, so the file count is its member count, and it compares in subset mode.
    const fileCount = Array.isArray(record.files) ? record.files.length : 0, comparison = lookupComparisonFor(doc), subset = comparison === 'subset';
    const aliases = Array.isArray(record.aliases) ? record.aliases : [];
    const queries = Array.isArray(record.queries) ? record.queries : [];
    const exhausted = storedExhausted(record.exhausted);
    let stage: LookupItunesStage | null = storedItunesStage(record.itunesStage);
    // An existing-Album review's Track-title searches are the plan's tail from `first` (-1: none, and the run behaves as before).
    const first = queries.findIndex(isTrackTitleLookupQuery);
    const undecided = () => first >= 0 && next.trackTitleSearch !== 'sent' && next.trackTitleSearch !== 'skipped';
    /** The bound a title search admits under: 15 while the Track-title searches are undecided, else 25. */
    const titleBound = () => undecided() ? JOB.candidates - JOB.trackTitleCandidates : JOB.candidates;
    const namesArtist = (query: unknown) => typeof (query as { query?: { artist?: unknown } } | null)?.query?.artist === 'string';
    const creditedTitles = first > 0 && queries.slice(0, first).some(namesArtist);
    const rank = () => rankLookupWithinBudget(next.candidates, doc, now, { searchComplete: next.searchComplete === true && stage?.complete !== false,
        // A review's iTunes stage keeps its own exact-count flag, so leaving out larger collections never blocks that preselection.
        ...(subset ? { exactSearchComplete: next.exactSearchComplete === true && (stage?.exactComplete ?? stage?.complete) !== false } : {}),
        aliases: lookupFetchedAliases(next), localized: lookupLocalizedGroups({ itunesStage: stage }) });
    /**
     * Merges a search's releases while fewer than `bound` candidates are known and records whether it left out one that could match
     * (and, in subset mode, one of exactly the member count).
     */
    const admit = (found: readonly FoundRelease[], basis: Parameters<typeof mergeLookupCandidates>[2], complete: boolean, bound: number = JOB.candidates): Partial<MetadataLookupRecord> => {
        // A record from a release before these fields stays partial.
        if (!subset) {
            const candidates = mergeLookupCandidates(next.candidates, found, basis, fileCount, 'exact', bound);
            return { candidates, searchComplete: next.searchComplete === true && complete && lookupHitsAdmitted(candidates, found, fileCount) };
        }
        const candidates = mergeLookupCandidates(next.candidates, found, basis, fileCount, 'subset', bound), admitted = lookupSubsetHitsAdmitted(candidates, found, fileCount);
        return { candidates, searchComplete: next.searchComplete === true && complete && admitted.subset, exactSearchComplete: next.exactSearchComplete === true && complete && admitted.exact };
    };
    /**
     * Whether the iTunes stage is not needed: a matching group holds a release first found other than by a Track title (one found
     * only that way never stops it), or, in a review, such a release has the searched title, a credit that agrees and tracks that
     * fit (catalogReviewItunesSkippable). A skipped stage stores nothing and leaves both completeness flags as they are.
     */
    const itunesNotNeeded = () => {
        const ranking = rank().ranking, byTrackTitle = (key: string) => next.candidates.find(candidate => candidate.key === key)?.basis === 'trackTitle';
        return ranking.groups.some(group => group.memberKeys.some(key => !byTrackTitle(key)))
            || (subset && catalogReviewItunesSkippable(doc, next.input, ranking.candidates, byTrackTitle));
    };
    /**
     * The next Track-title search from `from` while fewer than 25 candidates are known (`queryIndex` moves to it): alone when a title
     * search of the plan named an Artist and none of them returned a release, and then passed over when it weighs below eight; null
     * (`queryIndex` past the plan) once none is left. A search not handed out never makes the comparison partial.
     */
    const nextTrackTitleSearch = (from: number): LookupAction | null => {
        for (let index = from; index < queries.length && next.candidates.length < JOB.candidates; index++) {
            const planned = queries[index];
            if (!isTrackTitleLookupQuery(planned)) continue;
            const query = creditedTitles && next.creditFound !== true ? { recording: planned.query.recording } : planned.query;
            if (query.artist === undefined && trackTitleWeight(query.recording) < UNCREDITED_TRACK_TITLE_MIN_WEIGHT) continue;
            next = { ...next, queryIndex: index };
            return { kind: 'search', index, query: { ...planned, query } };
        }
        next = { ...next, queryIndex: queries.length };
        return null;
    };
    if (result?.kind === 'notConfigured') return { next: endLookupRun(record, 'unavailable', 'notConfigured', now), step: idleLookupStep };
    if (result?.kind === 'failed' && next.phase === 'aliases') next.aliases = failPendingAliases(aliases);
    else if (result?.kind === 'aliases') next.aliases = recordAliases(aliases, result.action, { state: result.names ? 'fetched' : 'missing', names: result.names ?? [] });
    else if (result?.kind === 'refused' && result.action.kind === 'aliases') next.aliases = recordAliases(aliases, result.action, { state: 'failed', names: [] });
    else if (result?.kind === 'failed' && result.source === 'musicbrainz' && next.phase === 'search' && isTrackTitleLookupQuery(queries[next.queryIndex])) {
        // An optional Track-title search the source did not answer ends them: no attempt is counted, no retry is scheduled and no
        // source is exhausted; the comparison counts as partial and the run continues in this step with the candidates it has.
        next = { ...next, queryIndex: queries.length, searchComplete: false, ...(subset ? { exactSearchComplete: false } : {}) };
    } else if (result?.kind === 'failed') {
        const source = result.source === 'itunes' ? 'itunes' : 'musicbrainz';
        const counted = record.attempts?.[source];
        const failures = (Number.isSafeInteger(counted) ? counted as number : 0) + 1;
        const retryAt = lookupRetryAt(failures, now, result.retryAfterMs, { rateLimited: result.failure === 'rateLimited' });
        // A refused gate and a throttled source are busy; only an outage or a timeout is unavailable.
        const failed: MetadataLookupIssue & ('sourceBusy' | 'sourceUnavailable') = result.failure === 'unavailable' ? 'sourceUnavailable' : 'sourceBusy';
        next = { ...next, attempts: { ...record.attempts, [source]: failures } };
        // A retry its grant would not reach counts as exhausted, so a run never stays blocking past its grant.
        if (retryAt && retryAt < record.grantExpiresAt) return { next: { ...next, state: 'retrying', issue: failed, retryAt, leaseOwner: null, leaseUntil: null }, step: idleLookupStep };
        if (source === 'itunes') {
            exhausted.itunes = failed;
            if (stage) stage = itunesUnavailable(stage, fileCount);
        } else {
            const searching = next.phase === 'search', skip = undecided();
            // A search phase keeps the issue it ended with (as it ended the run before iTunes); details report an outage. Undecided
            // Track-title searches are skipped, since nothing more is sent to MusicBrainz.
            exhausted.musicbrainz = searching ? failed : 'sourceUnavailable';
            next = { ...next, queryIndex: queries.length, candidates: next.candidates.map(candidate => candidate.details === 'pending' ? { ...candidate, details: 'failed' } : candidate),
                ...(skip ? { trackTitleSearch: 'skipped' as const } : {}) };
            if (!stage) {
                stage = !itunesNotNeeded() ? startItunesStage(queries, searching ? 'searchUnavailable' : 'noMatch', comparison) : null;
                if (!stage && searching) return { next: endLookupRun({ ...next, exhausted }, 'unavailable', failed, now), step: idleLookupStep };
            }
        }
    } else if (result?.kind === 'found' && result.action.kind === 'search' && next.phase === 'search' && next.queryIndex === result.action.index) {
        // A Track-title search admits at most 5 more releases; a title search, 15 while they are undecided.
        const trackTitle = isTrackTitleLookupQuery(result.action.query);
        const bound = trackTitle ? Math.min(JOB.candidates, next.candidates.length + JOB.trackTitleCandidates / JOB.trackTitleSearches) : titleBound();
        const credited = !trackTitle && first >= 0 && namesArtist(result.action.query) && result.found.some(item => normalizeMusicBrainzId(item.releaseId) !== null);
        next = { ...next, ...admit(result.found, result.action.query.basis, result.complete, bound), queryIndex: next.queryIndex + 1, ...(credited ? { creditFound: true as const } : {}) };
    } else if (result?.kind === 'found' && result.action.kind === 'bridge' && stage?.bridge && stage.bridgeIndex === result.action.index) {
        // Bridged releases join like any search's (plausible first, the shared bound), and a bridge that left one out is partial.
        next = { ...next, ...admit(result.found, result.action.query.basis, result.complete) };
        stage = recordBridgeAnswer(stage, result.action.index, result.found.some(item => normalizeMusicBrainzId(item.releaseId) !== null) ? 'found' : 'none');
    } else if (result?.kind === 'itunes' && stage) {
        stage = recordItunesAnswer(stage, result.action.index, result.result, lookupEvidenceFor(doc), comparison);
    } else if (result?.kind === 'itunesCollection' && stage) {
        const item = stage.items.find(entry => entry.key === result.action.itemKey && entry.collection === 'pending');
        const candidate = item ? itunesCandidate(item, result.result) : null;
        const admitted = candidate ? admitItunesCandidate(next.candidates, candidate) : null;
        if (admitted) next = { ...next, candidates: admitted };
        if (item) stage = recordItunesCollection(stage, item.key, !candidate ? 'missing' : admitted ? 'fetched' : 'skipped', fileCount);
    } else if (result?.kind === 'details') {
        next.candidates = recordLookupDetails(next.candidates, result.action.releaseId, result.release);
    } else if (result?.kind === 'refused') {
        const action = result.action;
        if (action.kind === 'search' && next.phase === 'search' && next.queryIndex === action.index) {
            // A refused search was never sent: a Track-title one is passed over like any not sent, and only another makes it partial.
            next = { ...next, queryIndex: next.queryIndex + 1,
                ...(isTrackTitleLookupQuery(action.query) ? {} : { searchComplete: false, ...(subset ? { exactSearchComplete: false } : {}) }) };
        }
        else if (action.kind === 'details') next.candidates = recordLookupDetails(next.candidates, action.releaseId, 'failed');
        else if (action.kind === 'itunes' && stage) stage = skipItunesRequest(stage, action.index);
        else if (action.kind === 'bridge' && stage) stage = recordBridgeAnswer(stage, action.index, 'refused');
        else if (action.kind === 'itunesCollection' && stage) stage = recordItunesCollection(stage, action.itemKey, 'missing', fileCount);
    }
    const musicBrainzExhausted = exhausted.musicbrainz !== undefined;
    // A submitted run uses busy mode until its first failed attempt of either source; automatic runs (also reruns of submitted text)
    // and manual retries wait.
    const mode: LookupGateMode = next.grantSource === 'submit' && !next.attempts?.musicbrainz && !next.attempts?.itunes ? 'busy' : 'wait';
    const running = (action: LookupAction, phase: MetadataLookupRecord['phase']) => ({
        next: { ...next, itunesStage: stage, exhausted, state: 'running' as const, issue: null, phase, retryAt: null, leaseUntil: new Date(now.getTime() + JOB.leaseMs),
            // Stored before the request is sent, so the folder allowance is spent only once a folder name may have left.
            folderUsed: next.folderUsed === true || (action.kind === 'search' && action.query?.basis === 'folder') },
        // A Track-title search waits for its gate even in a submitted run.
        step: { action, mode: action.kind === 'search' && isTrackTitleLookupQuery(action.query) ? 'wait' as const : mode }
    });
    if (next.phase === 'search') {
        let index = next.queryIndex;
        // The fallbacks after a search are sent together, and only when no candidate is known as they start (one spelling alone
        // would compare fewer editions); skipped ones are never handed out, so they spend no folder allowance.
        const fallback = (at: number) => at < queries.length && isFallbackLookupQuery(queries[at]);
        if (fallback(index) && !fallback(index - 1) && next.candidates.length > 0) while (fallback(index)) index++;
        next = { ...next, queryIndex: index };
        if (first >= 0 && index >= first) {
            if (next.trackTitleSearch === 'sent') { const action = nextTrackTitleSearch(index); if (action) return running(action, 'search'); }
            else if (next.trackTitleSearch === 'skipped') next = { ...next, queryIndex: queries.length };
            // Undecided: nothing is sent here; the decision follows the details, and reaching it this way is never a bound stop.
        } else if (index < queries.length) {
            if (next.candidates.length < titleBound()) return running({ kind: 'search', index, query: queries[index] }, 'search');
            // The bound ended the search before a planned query ran; undecided Track-title searches still come next.
            next.searchComplete = false;
            if (subset) next.exactSearchComplete = false;
            if (undecided()) next.queryIndex = first;
        }
    }
    if (next.phase !== 'aliases') {
        // The stage's iTunes requests, then its bridge searches, go before the bridged releases' details.
        if (stage) {
            const searched = nextItunesSearchAction(stage, musicBrainzExhausted);
            stage = searched.stage;
            if (searched.action) return running(searched.action, searched.action.kind === 'bridge' ? 'bridge' : 'itunes');
        }
        // Subset mode fetches the fewest extra tracks first (the first stored on a tie); otherwise plausible counts first.
        const pending = subset
            ? next.candidates.filter(candidate => candidate.details === 'pending').reduce<StoredLookupCandidate | undefined>((best, candidate) =>
                !best || lookupSurplusRank(lookupAudioTrackCount(candidate), fileCount) < lookupSurplusRank(lookupAudioTrackCount(best), fileCount) ? candidate : best, undefined)
            : next.candidates.find(candidate => candidate.details === 'pending' && lookupTrackCountPlausible(lookupReportedTrackCount(candidate), fileCount))
                ?? next.candidates.find(candidate => candidate.details === 'pending');
        if (pending) return running({ kind: 'details', releaseId: pending.releaseId }, 'details');
        // Track-title searches are decided once the title searches' releases are compared, before the iTunes stage; a skip leaves
        // both completeness flags as they are.
        if (undecided()) {
            const ranking = rank().ranking;
            const skip = stage !== null || musicBrainzExhausted || next.queryIndex > first || ranking.preselection !== null
                || (trackTitleLookupTiming(queries[first]) === 'noMatchOrPartial' && ranking.groups.length > 0 && !ranking.disclosure.partialComparison);
            if (skip) next = { ...next, trackTitleSearch: 'skipped', queryIndex: queries.length };
            else {
                next = { ...next, trackTitleSearch: 'sent' };
                const action = nextTrackTitleSearch(first);
                if (action) return running(action, 'search');
            }
        }
        // MusicBrainz answered without a matching candidate (one found only by Track titles does not count) and, in a review,
        // without a fitting release of the searched title: the stage starts once, when the run's queries give an iTunes request.
        if (!stage && !itunesNotNeeded()) {
            stage = startItunesStage(queries, 'noMatch', comparison);
            const searched = stage ? nextItunesSearchAction(stage, musicBrainzExhausted) : null;
            if (searched) stage = searched.stage;
            if (searched?.action) return running(searched.action, searched.action.kind === 'bridge' ? 'bridge' : 'itunes');
        }
        if (stage) {
            const collected = nextItunesCollectionAction(stage, next.candidates.length, musicBrainzExhausted, fileCount);
            stage = collected.stage;
            if (collected.action) return running(collected.action, 'itunes');
        }
        // Aliases follow in ranked order; an exhausted source is not asked again for them.
        const targets = musicBrainzExhausted ? [] : lookupAliasTargets(next.candidates, rank().ranking, { trackArtists: subset });
        if (targets.length) next = { ...next, aliases: targets };
    }
    const target = (Array.isArray(next.aliases) ? next.aliases : []).find(entry => entry.state === 'pending');
    if (target) return { next: running({ kind: 'aliases', entity: target.kind, id: target.id }, 'aliases').next, step: { action: { kind: 'aliases', entity: target.kind, id: target.id }, mode: 'wait' } };
    next = { ...next, itunesStage: stage, exhausted };
    // A stage that MusicBrainz's unavailable searches started and that found no iTunes-only candidate ends unavailable, as before.
    if (stage?.reason === 'searchUnavailable' && !next.candidates.some(candidate => candidate.source === 'itunes')) {
        return { next: endLookupRun(next, 'unavailable', exhausted.musicbrainz ?? 'sourceUnavailable', now), step: idleLookupStep };
    }
    // The single place where a run is ranked as it completes; the service applies its preselection in the same step.
    const ranked = rank();
    return { next: endLookupRun(next, 'complete', exhausted.musicbrainz ?? null, now, { phase: 'done', outcome: next.candidates.length ? 'candidates' : 'noRelease',
        candidates: ranked.candidates, ranking: ranked.ranking }), step: idleLookupStep };
}
